```ts
import type { LedgerHashInput } from "@/lib/ledger/hash";

/**
 * Full attendance event lifecycle ... 
 */
export const ATTENDANCE_STATES = [
  "initiated",
  "authenticated",
  "session_verified",
  "presence_evaluated",
  "risk_evaluated",
  "step_up",
  "verified",
  "flagged",
  "rejected",
  "corrected",
] as const;

export type AttendanceEventState = (typeof ATTENDANCE_STATES)[number];

export const ATTENDANCE_ORIGINS = ["online", "offline-faculty", "mobile"] as const;

export type AttendanceOrigin = (typeof ATTENDANCE_ORIGINS)[number];

/** Terminal decision states a correction may overwrite. */
export const CORRECTIONABLE_STATES = ["verified", "flagged", "rejected"] as const;

export type CorrectionableState = (typeof CORRECTIONABLE_STATES)[number];

/**
 * Linear pipeline order... intermediates before decision states.
 */
const PIPELINE_PROGRESSION: readonly AttendanceEventState[] = [
  "initiated",
  "authenticated",
  "session_verified",
  "presence_evaluated",
  "risk_evaluated",
];

const DECISION_STATES: readonly AttendanceEventState[] = ["step_up", "verified", "flagged", "rejected"];

/** Every state except "corrected" may begin an attempt entry; corrections only overwrite existing events. */
export function isStartableState(state: AttendanceEventState): boolean {
  return state !== "corrected";
}

/** state==="corrected" iff correctsEventId is present; regular events must not carry it. */
export function isValidCorrection(state: AttendanceEventState, correctsEventId: string | undefined): boolean {
  if (state === "corrected") return correctsEventId !== undefined;
  return correctsEventId === undefined;
}

/**
 * Whether `next` may follow `prev` inside the progressive check-in pipeline.
 * Intermediates advance one step at a time; any intermediate may jump straight
 * to a decision state (the shape today's single-shot writers produce).
 * Corrections are overwrites, not pipeline steps, so they never follow.
 */
export function canFollowInPipeline(prev: AttendanceEventState, next: AttendanceEventState): boolean {
  const prevIndex = PIPELINE_PROGRESSION.indexOf(prev);
  if (prevIndex === -1) return false;
  if (next === "corrected") return false;
  if (DECISION_STATES.includes(next)) return true;
  return PIPELINE_PROGRESSION.indexOf(next) === prevIndex + 1;
}

/** event_ledger type stamped on every per-student attendance chain entry. */
export const ATTENDANCE_CHAIN_EVENT_TYPE = "attendance.session_checkin";

export type AttendanceChainFields = {
  institutionId: string;
  studentId: string;
  sectionId: string;
  sessionId?: string;
  state: AttendanceEventState;
  origin: AttendanceOrigin;
  policyVersion?: string;
  correctsEventId?: string;
};

function attendanceChainPayload(event: AttendanceChainFields): Record<string, unknown> {
  return {
    studentId: event.studentId,
    ...(event.sessionId !== undefined ? { sessionId: event.sessionId } : {}),
    sectionId: event.sectionId,
    state: event.state,
    origin: event.origin,
    ...(event.policyVersion !== undefined ? { policyVersion: event.policyVersion } : {}),
    ...(event.correctsEventId !== undefined ? { correctsEventId: event.correctsEventId } : {}),
  };
}
```

