```ts
export const verifyChain = query({
  args: { actorToken: v.string(), fromSeq: v.optional(v.number()), limit: v.optional(v.number()) },
  handler: async (ctx, args) => {
    const caller = await resolveCaller(ctx, args.actorToken);
    if (caller.role !== "admin" && caller.role !== "auditor") throw new ConvexError("unauthorized");

    const fromSeq = Math.max(0, Math.floor(args.fromSeq ?? 0));
    const limit = Math.min(Math.max(1, Math.floor(args.limit ?? 500)), MAX_VERIFY_WINDOW);

    const predecessorRequired = fromSeq > 0;
    let predecessorHash: string | undefined;
    let oldestSurvivingSeq: number | null = null;
    if (predecessorRequired) {
      const predecessor = await ctx.db.query("event_ledger")
        .withIndex("by_institution_seq", q => q.eq("institutionId", caller.institutionId))
        .filter(q => q.eq(q.field("seq"), fromSeq - 1))
        .first();
      if (predecessor != null) predecessorHash = predecessor.eventHash;
      else {
        const oldest = await ctx.db.query("event_ledger")
          .withIndex("by_institution_seq", q => q.eq("institutionId", caller.institutionId))
          .order("asc")
          .first();
        oldestSurvivingSeq = oldest?.seq ?? null;
      }
    }

    const window = await ctx.db.query("event_ledger")
      .withIndex("by_institution_seq", q => q.eq("institutionId", caller.institutionId))
      .filter(q => q.gte(q.field("seq"), fromSeq))
      .order("asc")
      .take(limit + 1);

    return verifyChainWindow({
      window, fromSeq, limit, predecessorHash, predecessorRequired, oldestSurvivingSeq,
      recomputeHash: async (row) => computeEventHash({
        institutionId: row.institutionId,
        category: row.category as LedgerEventCategory,
        type: row.type,
        actorUserId: row.actorUserId,
        subjectUserId: row.subjectUserId,
        deviceId: row.deviceId,
        payload: row.payload as Record<string, unknown>,
        seq: row.seq,
        prevEventHash: row.prevEventHash,
      }),
    });
  },
});
