type ChainQuery = typeof api.ledger.verifyChain | typeof api.ledger.verifyAttendanceChain;
type ChainWindow = FunctionReturnType<typeof api.ledger.verifyChain>;

async function walkChain(convex: ReturnType<typeof useConvex>, query: ChainQuery, actorToken: string): Promise<ChainStatus> {
  let cursorSeq: number | undefined;
  let verifiedCount = 0;
  for (let window = 0; window < MAX_CHAIN_WINDOWS; window += 1) {
    const result: ChainWindow = await convex.query(query, {
      actorToken,
      limit: 500,
      ...(cursorSeq !== undefined ? { fromSeq: cursorSeq } : {}),
    });
    if (!result.valid) return { state: "broken", brokenAtSeq: result.brokenAtSeq ?? -1 };
    verifiedCount += result.count;
    if (!("nextCursor" in result) || result.nextCursor === undefined) {
      return { state: "valid", count: verifiedCount };
    }
    cursorSeq = result.nextCursor;
  }
  return { state: "valid", count: verifiedCount };
}
```

