  predecessorHash: string | undefined;
  predecessorRequired: boolean;
  oldestSurvivingSeq: number | null;
}> {
  if (fromSeq === 0) {
    return { predecessorHash: undefined, predecessorRequired: false, oldestSurvivingSeq: null };
  }
